#pragma once

#include "LoggerForwardDecls.hpp"
#include <memory>
#include <string>
#include <chrono>
#include <sstream>
#include <vector>
#include <experimental/source_location>

namespace ws::log {

class Event {
public:
    using Ptr = std::shared_ptr<Event>;

    static Ptr Create(Level level, 
                      std::experimental::source_location location = std::experimental::source_location::current(),
                      uint32_t thread_id = 0,
                      time_point time = std::chrono::system_clock::now());

    std::ostringstream& MessageStream();

private:
    Event(Level level, 
          std::experimental::source_location location,
          uint32_t thread_id,
          time_point time);

    Level m_level;
    std::string m_message;
    std::experimental::source_location m_location;
    uint32_t m_thread_id;
    time_point m_time;
};

} // namespace ws::log

#pragma once

#include "LoggerForwardDecls.hpp"
#include <memory>
#include <string>
#include <chrono>
#include <sstream>
#include <vector>
#include <experimental/source_location>

namespace ws::log {

class Logger {
public:
    using Ptr = std::shared_ptr<Logger>;

    void Log(Event::Ptr event);
    void AddAppender(Appender::Ptr appender);
    void RemoveAppender(Appender::Ptr appender);
    void SetDefaultFormatter(Formatter::Ptr formatter);

private:
    std::vector<Appender::Ptr> m_appenders;
    Formatter::Ptr m_default_formatter;
};

} // namespace ws::log

#pragma once

#include "LoggerForwardDecls.hpp"
#include <memory>
#include <string>
#include <chrono>
#include <sstream>
#include <vector>
#include <experimental/source_location>

namespace ws::log {

class Formatter {
public:
    using Ptr = std::shared_ptr<Formatter>;

    virtual ~Formatter() = default;
    virtual std::string Format(Logger& logger, Event& event) = 0;
};

} // namespace ws::log

